import{_ as a,o as i,c as s,ae as t}from"./chunks/framework.C4zpkcTP.js";const g=JSON.parse('{"title":"Upgrading","description":"Upgrade Laravel Biometric Auth from v3 to v4. Padding names for phpseclib 3 and 4, single-use expiring challenges and a typed revoke failure.","frontmatter":{"title":"Upgrading","description":"Upgrade Laravel Biometric Auth from v3 to v4. Padding names for phpseclib 3 and 4, single-use expiring challenges and a typed revoke failure."},"headers":[],"relativePath":"laravel-biometric-auth/upgrading.md","filePath":"laravel-biometric-auth/upgrading.md"}'),o={name:"laravel-biometric-auth/upgrading.md"};function n(r,e,c,d,h,l){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="upgrading-to-v4-from-v3" tabindex="-1">Upgrading to v4 from v3 <a class="header-anchor" href="#upgrading-to-v4-from-v3" aria-label="Permalink to &quot;Upgrading to v4 from v3&quot;">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>PHP 8.1+ and Laravel 10 to 13. Laravel 9 is no longer supported.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> require</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> laranex/laravel-biometric-auth:^4.0</span></span></code></pre></div><p>The package no longer depends on <code>spatie/laravel-package-tools</code>. The publish tags <code>biometric-auth-config</code> and <code>biometric-auth-migrations</code> are unchanged, and the new <code>biometric-auth</code> tag publishes both.</p><h2 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h2><p>No database changes: the <code>biometrics</code> table and its columns are unchanged. If you published the migration under v3, keep it. The package detects a published <code>*_create_biometrics_table.php</code> and no longer loads its own copy; without one, the package migration now runs automatically.</p><h2 id="rsa-padding" tabindex="-1">RSA padding <a class="header-anchor" href="#rsa-padding" aria-label="Permalink to &quot;RSA padding&quot;">​</a></h2><p>phpseclib 4 is supported alongside phpseclib 3. phpseclib 4 moved to the <code>phpseclib4</code> namespace and renumbered the RSA signature constants, so <code>rsa.encryption_padding</code> now takes a name. If you published <code>config/biometric-auth.php</code>, update it:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Before</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;encryption_padding&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\phpseclib3\\Crypt\\RSA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SIGNATURE_PKCS1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// After</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;encryption_padding&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;pkcs1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// or &#39;pss&#39;</span></span></code></pre></div><p>The old constant keeps working while you stay on phpseclib 3, but it is a fatal error on phpseclib 4 (the class no longer exists). Unknown names throw <code>InvalidArgumentException</code>.</p><h2 id="single-use-expiring-challenges" tabindex="-1">Single-use, expiring challenges <a class="header-anchor" href="#single-use-expiring-challenges" aria-label="Permalink to &quot;Single-use, expiring challenges&quot;">​</a></h2><p><code>verifyBiometric()</code> now clears the challenge after a successful verification, so a captured signature cannot be replayed. Clients must request a new challenge with <code>getBiometric()</code> after every successful verification. Failed attempts keep the challenge so the device can retry, up to <code>challenge.max_attempts</code> (5 by default, <code>BIOMETRIC_AUTH_CHALLENGE_MAX_ATTEMPTS</code>); then the challenge is cleared and the client must request a new one. Attempts are counted in the default cache store. Set the option to <code>0</code> to keep v3&#39;s unlimited retries.</p><p>Challenges now expire <code>challenge.ttl</code> seconds after they are issued (300 by default, <code>BIOMETRIC_AUTH_CHALLENGE_TTL</code>). <code>getBiometric()</code> replaces an expired challenge and <code>verifyBiometric()</code> throws <code>BiometricChallengeNotFoundException</code> for one, so devices must sign within that window. The issue time is the row&#39;s <code>updated_at</code>, so no column is added. Set the option to <code>0</code> to keep v3&#39;s challenges that never expire.</p><p><code>getBiometric()</code>, <code>verifyBiometric()</code> and <code>revokeBiometric()</code> throw <code>BiometricNotFoundException</code> for an id that is not a UUID instead of querying the database (which failed on PostgreSQL&#39;s native <code>uuid</code> column). <code>verifyBiometric()</code> decodes the signature as strict base64: a signature with characters outside the base64 alphabet returns <code>false</code>.</p><h2 id="revoking" tabindex="-1">Revoking <a class="header-anchor" href="#revoking" aria-label="Permalink to &quot;Revoking&quot;">​</a></h2><p><code>revokeBiometric()</code> throws <code>BiometricNotFoundException</code> when the biometric does not exist, is already revoked or belongs to another model. It previously failed with a PHP error on <code>null</code>. Catch the exception where you previously checked for a failure:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Laranex\\LaravelBiometricAuth\\Exceptions\\BiometricNotFoundException</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">try</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    $user</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">revokeBiometric</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($biometricId);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">catch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">BiometricNotFoundException</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    abort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">404</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="service-class" tabindex="-1">Service class <a class="header-anchor" href="#service-class" aria-label="Permalink to &quot;Service class&quot;">​</a></h2><p><code>LaravelBiometricAuth</code> now takes the config repository through its constructor. If you create it with <code>new</code>, resolve it instead:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Laranex\\LaravelBiometricAuth\\LaravelBiometricAuth</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>The <code>LaravelBiometricAuth</code> facade works as before.</p><h2 id="exceptions" tabindex="-1">Exceptions <a class="header-anchor" href="#exceptions" aria-label="Permalink to &quot;Exceptions&quot;">​</a></h2><p>The exceptions extend the new <code>BiometricException</code> base class and their constructors are typed: <code>string $message</code>, <code>?int $code</code>, <code>?Throwable $previous</code>.</p><p>The default code is now an HTTP status instead of <code>500</code>: <code>404</code> for <code>BiometricNotFoundException</code>, <code>422</code> for <code>BiometricChallengeNotFoundException</code> and <code>InvalidPublicKeyException</code>. They are renderable, so an uncaught exception in a JSON request returns <code>{&quot;message&quot;: &quot;...&quot;}</code> with that status instead of a <code>500</code> server error. If you relied on the <code>500</code> code or response, catch the exceptions yourself. See <a href="/laravel-biometric-auth/usage.html#exceptions">Exceptions</a>.</p><h2 id="morph-map" tabindex="-1">Morph map <a class="header-anchor" href="#morph-map" aria-label="Permalink to &quot;Morph map&quot;">​</a></h2><p><code>authenticable_type</code> is now stored through <code>getMorphClass()</code>. If your app uses a morph map, new rows store the alias instead of the class name. Existing rows with the class name keep resolving through the <code>instance</code> relation.</p><h2 id="new" tabindex="-1">New <a class="header-anchor" href="#new" aria-label="Permalink to &quot;New&quot;">​</a></h2><ul><li><code>HasBiometrics::biometrics()</code> morph-many relation.</li><li><code>Biometric::active()</code> scope.</li><li>The migration and the model read the table name from <code>biometric-auth.table</code>.</li></ul>`,29)])])}const u=a(o,[["render",n]]);export{g as __pageData,u as default};
